-- ============================================================
-- Rapid Killing: proc configuration
-- ============================================================
--
-- ProcFlags 256 = PROC_FLAG_DONE_SPELL_RANGED_DMG_CLASS, narrowed to the four
-- shots by family mask:
--
--   SpellFamilyMask0 133120 = Arcane Shot (0x800) | Aimed Shot (0x20000)
--   SpellFamilyMask1 1      = Steady Shot
--   SpellFamilyMask2 1      = Chimera Shot
--
-- The same four shots Lethal Instincts uses, which is deliberate: the
-- Marksmanship rotation now maintains two things by shooting.
--
-- Chance 100 on both ranks.  The rank difference lives entirely in the Rapid
-- Fire cooldown (-1.5 min / -3 min); the refresh does not scale, because a
-- refresh that only sometimes lands would make the redirect window feel random
-- rather than sustained.
--
-- AttributesMask 0: all four shots are real player casts, not triggered
-- children, so PROC_ATTR_TRIGGERED_CAN_PROC is not needed.

DELETE FROM `spell_proc` WHERE `SpellId` IN (34948, 34949);
